import{_ as c}from"./chunks/PageInfo.vue_vue_type_script_setup_true_lang.CY4CSaHW.js";import{_ as l}from"./chunks/Badge.BoOVOLnd.js";import{_ as n,o as d,c as i,j as o,a,E as t,a3 as p}from"./chunks/framework.DK8j89yW.js";import"./chunks/theme.B8gQcpPc.js";const _="/assets/BTPanel-Docker-Install.DcqTPIh6.png",m="/assets/BTPanel-Docker-Set-URL.CV7AWTF2.png",h="/assets/BTPanel-Docker-Search.e9iM-5gb.png",g="/assets/BTPanel-Docker-Install-Confirm.C9CrLCL0.png",k="/assets/BTPanel-Docker-Update-Image.DKq_y8Lg.png",L=JSON.parse('{"title":"在宝塔面板部署GsCore","description":"","frontmatter":{},"headers":[],"relativePath":"Started/BTPanel.md","filePath":"Started/BTPanel.md","lastUpdated":1786499878000}'),u={name:"Started/BTPanel.md"},f={id:"在宝塔面板部署gscore",tabindex:"-1"};function b(P,e,D,C,T,q){const r=l,s=c;return d(),i("div",null,[o("h1",f,[e[0]||(e[0]=a("在宝塔面板部署GsCore",-1)),t(r,{type:"danger",text:"简单"}),e[1]||(e[1]=a()),e[2]||(e[2]=o("a",{class:"header-anchor",href:"#在宝塔面板部署gscore","aria-label":'Permalink to "在宝塔面板部署GsCore<Badge type="danger" text="简单" />"'},"​",-1))]),t(s,{readTime:"2",words:"649"}),e[3]||(e[3]=p('<p><a href="https://www.bt.cn/new/index.html" target="_blank" rel="noreferrer">宝塔面板</a> 是一个安全高效、生产可用的 Linux/Windows 服务器运维面板。 GsCore 已上架至宝塔的 Docker 应用商店，支持<strong>一键安装</strong>。</p><h2 id="_1-安装宝塔面板" tabindex="-1">1. 安装宝塔面板 <a class="header-anchor" href="#_1-安装宝塔面板" aria-label="Permalink to &quot;1. 安装宝塔面板&quot;">​</a></h2><p>如果您还没有安装宝塔面板，请参考 <a href="https://docs.bt.cn/getting-started/quick-installation-of-bt-panel" target="_blank" rel="noreferrer">快速安装宝塔面板</a> 进行安装。</p><h2 id="_2-安装-docker" tabindex="-1">2. 安装 Docker <a class="header-anchor" href="#_2-安装-docker" aria-label="Permalink to &quot;2. 安装 Docker&quot;">​</a></h2><p>进入宝塔面板首页，点击左侧菜单的 <code>Docker</code>，若未安装 Docker，宝塔会提示并引导你一键安装 Docker 及 Docker Compose，按提示完成安装即可。</p><img src="'+_+'" alt="宝塔面板安装Docker"><h2 id="_3-设置加速-url-国内服务器用户" tabindex="-1">3. 设置加速 URL（国内服务器用户） <a class="header-anchor" href="#_3-设置加速-url-国内服务器用户" aria-label="Permalink to &quot;3. 设置加速 URL（国内服务器用户）&quot;">​</a></h2><p>进入宝塔面板页面后，点击左侧的 <code>Docker</code> → 点击顶部的 <code>设置</code>，在 <code>基础设置</code> 中找到 <code>加速 URL</code>，填入国内可用的镜像加速地址（例如 Docker 官方、阿里云容器镜像服务的个人加速地址），保存即可加速镜像拉取。</p><img src="'+m+'" alt="宝塔面板设置加速URL"><h2 id="_4-安装-gscore" tabindex="-1">4. 安装 GsCore <a class="header-anchor" href="#_4-安装-gscore" aria-label="Permalink to &quot;4. 安装 GsCore&quot;">​</a></h2><p>进入 <code>Docker</code> 的 <code>应用商店</code>，在搜索框中搜索 <code>早柚核心</code>。</p><img src="'+h+'" alt="宝塔面板搜索早柚核心"><p>点击 <code>安装</code>，按照安装页面提示填写配置（默认端口为 <code>8765</code>），点击 <code>安装</code>，等待安装成功。</p><img src="'+g+'" alt="宝塔面板安装早柚核心"><div class="tip custom-block"><p class="custom-block-title">💡 提醒</p><p>如果在应用商店中搜索不到早柚核心，请点击应用商店右上角的 <code>更新应用列表</code>，等待应用列表刷新完成后，再进行搜索。</p></div><h2 id="_5-访问-gscore" tabindex="-1">5. 访问 GsCore <a class="header-anchor" href="#_5-访问-gscore" aria-label="Permalink to &quot;5. 访问 GsCore&quot;">​</a></h2><p>访问 <code>http://IP:8765/app</code> 即可进入 GsCore 的网页控制台。</p><ul><li>首次进入需要注册，注册码在 <code>gsuid_core/data/config.json</code> 的 <code>REGISTER_CODE</code> 字段中</li><li>更多控制台说明见 <a href="./WebConsole.html">网页控制台</a></li></ul><h2 id="_6-后续操作" tabindex="-1">6. 后续操作 <a class="header-anchor" href="#_6-后续操作" aria-label="Permalink to &quot;6. 后续操作&quot;">​</a></h2><ul><li>GsCore 只是&quot;核心&quot;，还需要接入 Bot 才能收发消息，请参考 <a href="./../LinkBots/AdapterList.html">适配Bot列表</a></li><li>部署完成后在网页控制台中即可安装/管理插件，参考 <a href="./../InstallPlugins/InstallPlugins.html">安装插件</a></li></ul><div class="tip custom-block"><p class="custom-block-title">💡 提醒</p><p>数据持久化：容器内的玩家账号、数据库等核心资产存放在宿主机数据目录中，容器重建后数据不会丢失。</p><p>更新镜像：进入 <code>Docker</code> → <code>容器编排</code>，找到早柚核心的编排，点击 <code>更新镜像</code> 即可更新到最新版本。</p><img src="'+k+'" alt="宝塔面板更新早柚核心镜像"></div>',21))])}const S=n(u,[["render",b]]);export{L as __pageData,S as default};
